head.script:
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "SoftwareApplication",
      "name": "projectAndNote: Focus & Notes",
      "operatingSystem": "Android",
      "applicationCategory": "ProductivityApplication",
      "offers": {
        "@type": "Offer",
        "price": "0.00",
        "priceCurrency": "USD"
      },
      "description": "Block notes, focus sprints, full-screen task alarms, and 100% offline SQLite storage on Android."
    },
    {
      "@type": "Organization",
      "name": "projectAndNote",
      "url": "https://projectandnote.com",
      "logo": "https://projectandnote.com/projectAndNoteLogo.svg",
      "contactPoint": {
        "@type": "ContactPoint",
        "email": "contact.hanuut@gmail.com",
        "contactType": "customer support"
      }
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is projectAndNote?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "projectAndNote is a premium, local-first Android workspace combining a universal block-based document editor, native Focus Sprints with Energy Ball visualizer, and full-screen deadline alarms."
          }
        },
        {
          "@type": "Question",
          "name": "Is projectAndNote 100% offline?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. All notes, checklists, voice memos, and images are stored in a local SQLite database on your device. No cloud syncing and zero accounts required."
          }
        }
      ]
    }
  ]
}
